{"content":"import hashlib
import hmac
import json

from payhook.errors import InvalidNotification

_TOLERANCE_SECONDS = 300
_SIGNATURE_PREFIX = "v1="


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    timestamp_header = headers.get("X-Pay-Timestamp")
    signature_header = headers.get("X-Pay-Signature")
    if not timestamp_header or not signature_header:
        raise InvalidNotification("missing timestamp or signature header")

    try:
        signed_timestamp = timestamp_header.encode("ascii")
    except (AttributeError, UnicodeEncodeError):
        raise InvalidNotification("malformed timestamp header") from None

    if not signature_header.startswith(_SIGNATURE_PREFIX):
        raise InvalidNotification("unsupported signature scheme")
    provided_digest = signature_header[len(_SIGNATURE_PREFIX):]

    expected_digest = hmac.new(
        secret, signed_timestamp + b"." + raw_body, hashlib.sha256
    ).hexdigest()
    try:
        signature_matches = hmac.compare_digest(expected_digest, provided_digest)
    except TypeError:
        signature_matches = False
    if not signature_matches:
        raise InvalidNotification("signature mismatch")

    try:
        timestamp = int(timestamp_header)
    except ValueError:
        raise InvalidNotification("malformed timestamp header") from None
    if abs(timestamp - now) > _TOLERANCE_SECONDS:
        raise InvalidNotification("stale timestamp")

    try:
        text = raw_body.decode("utf-8")
    except (AttributeError, UnicodeDecodeError):
        raise InvalidNotification("body is not UTF-8 JSON") from None
    try:
        event = json.loads(text)
    except json.JSONDecodeError:
        raise InvalidNotification("malformed JSON body") from None
    if not isinstance(event, dict):
        raise InvalidNotification("body is not a JSON object")

    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("invalid account_id")
    if (not isinstance(amount_minor, int) or isinstance(amount_minor, bool)
            or amount_minor < 0):
        raise InvalidNotification("invalid amount_minor")
    if (not isinstance(currency, str) or len(currency) != 3
            or not currency.isascii() or not currency.isalpha()
            or not currency.isupper()):
        raise InvalidNotification("invalid currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
